/*
 * node_modules/sqlite — node:sqlite-shaped API over the mochinode_sqlite
 * engine plugin (mochinode_sqlite.dll in mochi_modules/).
 *
 * The plugin talks to the system SQLite library (libsqlite3 / sqlite3.dll)
 * through prepared statements; this package adds the ergonomic layer:
 * open() -> { run, get, all, close }.
 */

import { loadNative } from '../mochinode/index.js';

const native = await loadNative('mochinode_sqlite.dll');

/* bind positional params (1-based) onto a prepared statement */
function _bind(st, params) {
    for (let i = 0; i < params.length; i++) {
        const v = params[i];
        const idx = i + 1;
        if (v === null || v === undefined) native.bindNull(st, idx);
        else if (typeof v === 'number') {
            if (Number.isInteger(v)) native.bindInt(st, idx, v);
            else native.bindDouble(st, idx, v);
        } else native.bindText(st, idx, String(v));
    }
    return st;
}

/* execute a prepared statement to completion (INSERT/UPDATE/DELETE) */
function _execPrepared(db, sql, params) {
    const st = native.prepare(db, sql);
    if (st < 0)
        throw new Error('sqlite: prepare failed for: ' + sql);
    _bind(st, params);
    const rc = native.step(st);          /* DONE(101) for write, ROW(100) first */
    native.finalize(st);
    return rc;
}

export function version() {
    return native.version();
}

export function open(path) {
    const db = native.open(path);
    if (db < 0)
        throw new Error('sqlite: open("' + path + '") failed');

    return {
        run(sql, ...params) {
            if (params.length === 0) {
                const rc = native.exec(db, sql);
                if (rc !== 0)
                    throw new Error('sqlite: exec rc=' + rc +
                                    ' (' + native.errmsg(db) + ')');
                return rc;
            }
            const rc = _execPrepared(db, sql, params);
            if (rc !== 0 && rc !== 100 && rc !== 101)
                throw new Error('sqlite: step rc=' + rc +
                                ' (' + native.errmsg(db) + ')');
            return rc;
        },

        all(sql, ...params) {
            const st = native.prepare(db, sql);
            if (st < 0)
                throw new Error('sqlite: prepare failed for: ' + sql);
            if (params.length) _bind(st, params);

            const n = native.columnCount(st);
            const names = [];
            for (let i = 0; i < n; i++) names.push(native.columnName(st, i));

            const rows = [];
            while (native.step(st) === 100) {
                const row = Object.create(null);
                for (let i = 0; i < n; i++) {
                    switch (native.columnType(st, i)) {
                        case 1: row[names[i]] = native.columnInt(st, i); break;
                        case 2: row[names[i]] = native.columnDouble(st, i); break;
                        case 3: row[names[i]] = native.columnText(st, i); break;
                        default: row[names[i]] = null; break;   /* NULL / BLOB */
                    }
                }
                rows.push(row);
            }
            native.finalize(st);
            return rows;
        },

        get(sql, ...params) {
            return this.all(sql, ...params)[0];
        },

        prepare(sql) {
            const st = native.prepare(db, sql);
            if (st < 0)
                throw new Error('sqlite: prepare failed for: ' + sql);
            const self = {
                bind(...params) { _bind(st, params); return self; },
                run(...params) {
                    _bind(st, params);
                    const rc = native.step(st);
                    native.reset(st);
                    native.clearBindings(st);
                    return rc;
                },
                all(...params) {
                    _bind(st, params);
                    const rows = [];
                    while (native.step(st) === 100) {
                        const row = Object.create(null);
                        for (let i = 0; i < native.columnCount(st); i++) {
                            const name = native.columnName(st, i);
                            switch (native.columnType(st, i)) {
                                case 1: row[name] = native.columnInt(st, i); break;
                                case 2: row[name] = native.columnDouble(st, i); break;
                                case 3: row[name] = native.columnText(st, i); break;
                                default: row[name] = null; break;
                            }
                        }
                        rows.push(row);
                    }
                    native.reset(st);
                    native.clearBindings(st);
                    return rows;
                },
                get(...params) { return self.all(...params)[0]; },
                finalize() { return native.finalize(st); },
            };
            return self;
        },

        close() {
            return native.close(db);
        },
    };
}

export default { version, open };
